entries.body:
{{if .IsUser}}
  <div class="msg user">
    <div class="msg-body">{{.Content}}</div>
    {{if .Attachments}}<div class="attachments">
      {{range .Attachments}}<span class="attachment{{if .ToGear}} to-gear{{end}}" title="{{.Title}}">
        <span class="attachment-name">{{.Name}}</span>
        <span class="muted">{{.Bytes}}</span>
        {{if .ToGear}}<span class="muted">→ gear</span>{{end}}
      </span>{{end}}
    </div>{{end}}
  </div>
{{else if .IsAssistant}}
  <div class="msg assistant">
    <div class="msg-body">
      {{/* Only a delegate is named. The orchestrator is the voice of the
           workspace, so labelling every one of its replies is the same noise
           as labelling your own. */}}
      {{if .Named}}<span class="who">{{.Who}}</span>{{end}}
      {{.Content}}
      {{if .Calls}}<span class="tool-chips">
        {{range .Calls}}<code class="chip">⚙ {{.Name}}</code>{{end}}
      </span>{{end}}
    </div>
  </div>
{{else if .IsToolResult}}
  <details class="msg-tool{{if .ToolFailed}} tool-error{{end}}">
    <summary>{{if .ToolFailed}}✗{{else}}✓{{end}} {{.ToolName}}</summary>
    <pre>{{.Content}}</pre>
  </details>
{{else if .IsDelegation}}
  <div class="msg delegation">
    <div class="msg-body"><span class="who">{{.Who}}</span>{{.Content}}</div>
  </div>
{{else}}
  <div class="msg {{.Kind}}"><div class="msg-body">{{.Content}}</div></div>
{{end}}

{{.AppHead}}
<script src="/cog/htmx.min.js" defer></script>
<script src="/cog/htmx-sse.js" defer></script>
{{template "cog.shell.tokens" .}}
{{range .Styles}}<link rel="stylesheet" href="{{.}}">
{{end}}{{range .Scripts}}<script type="module" src="{{.Src}}"{{if .Integrity}} integrity="{{.Integrity}}"{{end}}></script>
{{end}}{{template "cog.slot.head" .}}
